/* PintsNow app part: Check-in state + HTML, do / move check-in, "where are you" sheet. Moved from app.js without change (W2 step 8). Shared state: PN.s (app-core.js). */
(function () {
  "use strict";
  var PN = window.PN;
  // <split:imports> generated by scripts/split/move.mjs — do not edit
  var U, t, LIVE, PUSH_ON, $;
  PN.link(function () { U = PN.U; t = PN.t; LIVE = PN.LIVE; PUSH_ON = PN.PUSH_ON; $ = PN.$; });
  function rpc() { return PN.rpc.apply(null, arguments); }
  function parseData() { return PN.parseData.apply(null, arguments); }
  function toast() { return PN.toast.apply(null, arguments); }
  function errMsg() { return PN.errMsg.apply(null, arguments); }
  function openSheet() { return PN.openSheet.apply(null, arguments); }
  function closeSheet() { return PN.closeSheet.apply(null, arguments); }
  function el() { return PN.el.apply(null, arguments); }
  function btn() { return PN.btn.apply(null, arguments); }
  function tl() { return PN.tl.apply(null, arguments); }
  function nightEnd() { return PN.nightEnd.apply(null, arguments); }
  function myNight() { return PN.myNight.apply(null, arguments); }
  function updateCounts() { return PN.updateCounts.apply(null, arguments); }
  function refresh() { return PN.refresh.apply(null, arguments); }
  function getName() { return PN.getName.apply(null, arguments); }
  function withName() { return PN.withName.apply(null, arguments); }
  function signIn() { return PN.signIn.apply(null, arguments); }
  PN.put({
    myCheckin: myCheckin, syncMyCheckin: syncMyCheckin, checkinsAt: checkinsAt, checkinNamesHTML: checkinNamesHTML,
    checkinBtnHTML: checkinBtnHTML, doCheckin: doCheckin, moveCheckin: moveCheckin, askWhere: askWhere
  });
  // </split:imports>

  /* ---------- v10 Checka in ---------- */
  var CI_KEY = "olnu.checkin", CI_FRESH_MS = 3 * 3600e3, CI_STAY_M = 150;
  var ciBarById = {};    // bar id -> bar, for the button in an open popup
  PN.put({ ciBarById: ciBarById });   // <split:put/>
  // Own check-in on this phone: {id, name, lat, lng, at, until}. null when none or after 05:00.
  function myCheckin() {
    var c = U.ls.getJSON(CI_KEY, null);
    if (!c || !c.until || Date.now() > c.until || !isFinite(c.lat) || !isFinite(c.lng)) return null;
    return c;
  }
  // The server row wins (e.g. checked in on another phone, or the night ended).
  function syncMyCheckin() {
    var mine = null;
    PN.s.checkins.forEach(function (c) { if (c.is_mine) mine = c; });
    var loc = myCheckin();
    if (!mine) { if (loc && (Date.now() - loc.at) > 120e3) U.ls.del(CI_KEY); return; }
    var at = Date.parse(mine.created_at) || Date.now();
    if (!loc || loc.id !== mine.bar_id || Math.abs(loc.at - at) > 5000) {
      U.ls.setJSON(CI_KEY, { id: String(mine.bar_id), name: mine.bar_name, lat: +mine.lat, lng: +mine.lng, at: at, until: nightEnd() });
    }
  }
  function checkinsAt(bar) {
    var id = String(bar.id);
    return PN.s.checkins.filter(function (c) { return window.BARS.canonId(c.bar_id) === window.BARS.canonId(id); })
      .concat(window.DEMO ? window.DEMO.cisAt(bar) : []);   // 🎞️ visningsläge
  }
  // "Anton, Oskar + 2 till" (names: me + friends; strangers only as a count).
  function checkinNamesHTML(bar) {
    if (!LIVE || bar == null || bar.id == null) return "";
    var list = checkinsAt(bar), names = [], more = 0;
    list.forEach(function (c) {
      var n = c.is_mine ? (getName() || t("you")) : c.is_friend && c.name ? c.name : null;
      if (n && names.indexOf(n) < 0) names.push(n); else if (!n) more++;
    });
    if (names.length) return '<div class="pp-ci">' + U.esc(t("ciHere", names, more)) + "</div>";
    if (more) return '<div class="pp-ci">' + U.esc(t("ciHereAnon", more)) + "</div>";
    return "";
  }
  // The big "📍 Checka in" button (LIVE and signed in only).
  function checkinBtnHTML(bar) {
    if (!LIVE || bar == null || bar.id == null) return "";
    ciBarById[String(bar.id)] = bar;
    if (!PN.s.authed || PN.s.checkinState === "missing") return "";
    var me = myCheckin(), here = me && me.id === String(bar.id);
    if (here) return '<div class="ci-here">' + U.esc(t("ciDone")) + '</div><button type="button" class="ci-out" data-ciout="' + U.esc(String(bar.id)) + '">' +
      U.esc(tl("🚪 Checka ut", "🚪 Check out")) + "</button>";   // ux3: uxfix.js does the tap (check_out, 0162)
    return '<button type="button" class="ci-btn" data-ci="' + U.esc(String(bar.id)) + '"' + (here ? " disabled" : "") + ">" +
      U.esc(here ? t("ciDone") : t("ciBtn")) + "</button>";
  }
  function checkinHTML(bar) { return checkinNamesHTML(bar) + checkinBtnHTML(bar); }
  function doCheckin(button) {
    var bar = ciBarById[button.getAttribute("data-ci")];
    if (!bar || button.disabled) return;
    if (!LIVE) { toast(t("soonToast"), { id: "soon" }); return; }
    if (!PN.s.authed) { toast(t("connecting"), { id: "auth" }); signIn().then(function () { if (PN.s.authed) doCheckin(button); }); return; }   // ⚡ the 1st action makes the account
    window.FX.unlock();
    // Spökläge: nothing goes to the server, nobody is told.
    if (window.EXTRAS && window.EXTRAS.ghostOn && window.EXTRAS.ghostOn()) { toast(t("ciGhost"), { ms: 5000 }); return; }
    var name = String(bar.name || t("unnamedBar")).replace(/\s+/g, " ").trim().slice(0, 60);
    withName(function () {
      if (!$("sheet").hidden) closeSheet();   // the name sheet (first time only)
      button.disabled = true; button.classList.add("busy"); button.textContent = t("ciBusy");
      rpc("check_in", { p_bar_id: String(bar.id), p_bar_name: name, p_lat: bar.lat, p_lng: bar.lng }).then(function (r) {
        button.classList.remove("busy");
        var reset = function () { button.disabled = false; button.textContent = t("ciBtn"); };
        if (r.error) {
          reset();
          if (U.missing(r.error)) { PN.s.checkinState = "missing"; toast(t("ciOff"), { err: true }); return; }
          var c = U.errCode(r.error);
          toast(c === "outside_sweden" || c === "not_authenticated" ? errMsg(r.error) : t("ciFail"), { err: true });
          return;
        }
        var d = parseData(r.data);
        if (d.ok === false) { reset(); toast(t("ciWait", Math.max(1, d.wait_seconds | 0))); return; }
        U.ls.setJSON(CI_KEY, { id: String(bar.id), name: d.bar_name || name, lat: +bar.lat, lng: +bar.lng, at: Date.now(), until: nightEnd() });
        button.textContent = t("ciDone");
        try {   // ds51: the checked-in state at once (status + Checka ut), not a dead "Du ä incheckad här" button
          var ciTmp = document.createElement("div"), ciPar = button.parentNode; ciTmp.innerHTML = checkinBtnHTML(bar);
          if (ciPar && ciTmp.querySelector(".ci-out")) {
            while (ciTmp.firstChild) ciPar.insertBefore(ciTmp.firstChild, button);
            button.remove(); ciPar.classList.add("pn-bs-in");
            var ciEta = ciPar.querySelector(".pp-sec-eta"); if (ciEta) ciEta.classList.add("pn-bs-hide");
          }
        } catch (e) {}
        var lines = t("ciToasts") || [];
        toast(lines.length ? lines[Math.floor(Math.random() * lines.length)](d.bar_name || name) : t("ciDone"), { ms: 5000, cls: "skal" });
        window.FX.sound.clink(); window.FX.vibrate([18, 40, 18, 40, 60]);
        if (PUSH_ON && PN.s.client && PN.s.client.functions) {
          try { Promise.resolve(PN.s.client.functions.invoke("notify-group", { body: { event: "checkin", bar: d.bar_name || name } })).then(function () {}, function () {}); } catch (e) {}
        }
        updateCounts();
        refresh();
      });
    });
  }

  // fixJ T-07: checked in at A, a beer picked at B → check in at B. The server keeps one row per user (on conflict update).
  // Its 2-min cool-down (ok:false + wait_seconds) → one retry after the wait. Same bar (canonical id) = nothing.
  function moveCheckin(bar, again) {
    var ci = myCheckin();
    if (!ci || !bar || bar.id == null || !LIVE || !PN.s.authed || PN.s.checkinState === "missing") return;
    var canon = function (x) { try { return window.BARS && window.BARS.canonId ? window.BARS.canonId(String(x)) : String(x); } catch (e) { return String(x); } };
    if (canon(ci.id) === canon(bar.id) || !isFinite(bar.lat) || !isFinite(bar.lng)) return;
    if (window.EXTRAS && window.EXTRAS.ghostOn && window.EXTRAS.ghostOn()) return;
    var name = String(bar.name || t("unnamedBar")).replace(/\s+/g, " ").trim().slice(0, 60);
    rpc("check_in", { p_bar_id: String(bar.id), p_bar_name: name, p_lat: bar.lat, p_lng: bar.lng }).then(function (r) {
      if (r.error) { if (U.missing(r.error)) PN.s.checkinState = "missing"; return; }
      var d = parseData(r.data) || {};
      if (d.ok === false) {
        var w = d.wait_seconds | 0;
        if (!again && w > 0 && w <= 125) setTimeout(function () { moveCheckin(bar, true); }, (w + 1) * 1000);
        return;
      }
      U.ls.setJSON(CI_KEY, { id: String(bar.id), name: d.bar_name || name, lat: +bar.lat, lng: +bar.lng, at: Date.now(), until: nightEnd() });
      updateCounts(); refresh();
    });
  }
  // "Var dricker du?" — sometimes asks which bar you are at, so the beer counts there.
  // Asks: on the first beer tonight, when you moved > 150 m since the last pick, or now and then (1 in 4).
  // Else it reuses the last picked bar while you stay within 150 m of where you picked it.
  // v14: ✕ / backdrop / Escape / another sheet = CANCEL (no beer). Bars first, then restaurants/cafés (🍽️).
  // 🏠 Hemzon: the beer is posted as an area unless a bar or restaurant is picked.
  var WHERE_KEY = "olnu.where", WHERE_R = 400, WHERE_STAY = 150, WHERE_PLACE_R = 250;
  function askWhere(pos) {
    var lat = pos.coords.latitude, lng = pos.coords.longitude;
    var home = !!(window.PRIVACY && window.PRIVACY.inHome(lat, lng));
    var real = { lat: lat, lng: lng, precise: PN.s.prec === "exact" && !home, home: home };
    // v10: fresh own check-in (< 3 h) and still within 150 m of it → drink there, no question.
    var ci = myCheckin();
    if (ci && Date.now() - ci.at < CI_FRESH_MS && U.haversine(lat, lng, ci.lat, ci.lng) <= CI_STAY_M) {
      return Promise.resolve({ lat: ci.lat, lng: ci.lng, precise: PN.s.prec === "exact" });
    }
    // nf 2026-11-07: wait (max 1.2 s) for the restaurant tiles around this spot. They load only for the map VIEW, so the
    // first sheet away from the map view listed bars only ("my friend saw no restaurants"). Then 6 bars + 6 places (250 m).
    var wait = window.BARS && window.BARS.ensurePlacesP ? window.BARS.ensurePlacesP(lat, lng, 1, 1200) : Promise.resolve();
    return wait.then(function () { return askWhereList(lat, lng, real); });
  }
  function askWhereList(lat, lng, real) {
    var list = window.BARS && window.BARS.nearby ? window.BARS.nearby(lat, lng, WHERE_R, 6, { places: true, placeM: WHERE_PLACE_R, maxPlaces: 6 }) : [];
    if (!list.length) return Promise.resolve(real);
    var last = U.ls.getJSON(WHERE_KEY, null), night = myNight();
    var fresh = last && last.until > Date.now();
    var stayed = fresh && U.haversine(lat, lng, last.atLat, last.atLng) <= WHERE_STAY;
    var first = !night || !(night.count | 0);
    if (stayed && !first && Math.random() >= 0.25) {
      return Promise.resolve(last.bar ? { lat: last.bar.lat, lng: last.bar.lng, precise: true, _ciBar: last.bar } : real);   // fixJ T-07
    }
    return new Promise(function (resolve) {
      var done = false;
      function pick(bar) {
        if (done) return; done = true;
        U.ls.setJSON(WHERE_KEY, { atLat: lat, atLng: lng, until: nightEnd(),
          bar: bar ? { id: bar.id, name: bar.name, lat: bar.lat, lng: bar.lng } : null });
        closeSheet("pick");
        resolve(bar ? { lat: bar.lat, lng: bar.lng, precise: true, _ciBar: bar } : real);   // fixJ T-07: _ciBar = moves a check-in
      }
      openSheet(t("whereTitle"), function (body) {
        body.appendChild(el("p", { class: "muted", text: t("whereInfo") }));
        var bars = list.filter(function (x) { return !x.place; }), places = list.filter(function (x) { return x.place; });
        var row = function (x, i, emo) {
          var m = Math.round(x.d / 10) * 10;
          body.appendChild(el("div", { class: "row", style: "margin-top:8px" }, [
            btn(emo + " " + x.bar.name + "  · " + (m < 20 ? t("whereHere") : m + " m"), (i === 0 && emo === "🍺" ? "btn-amber " : "") + "btn-block" + (x.place ? " where-place" : ""), function () { pick(x.bar); })
          ]));
        };
        bars.forEach(function (x, i) { row(x, i, "🍺"); });
        if (places.length) {
          body.appendChild(el("p", { class: "muted where-sub", text: t("wherePlaces") }));
          places.forEach(function (x, i) { row(x, i, "🍽️"); });
        }
        // nf 2026-11-07: "📍 Fler ställen nära" = bars AND restaurants within 1 km (js/nearplaces.js), same pick.
        if (window.NEARPLACES && window.NEARPLACES.inline) {
          var moreBox = el("div", { class: "where-more-box" });
          var moreB = btn("📍 Fler ställen nära", "btn-ghost btn-block where-more", function () {
            moreB.remove();
            window.NEARPLACES.inline(moreBox, lat, lng, pick, list.map(function (x) { return x.bar.id; }));
          });
          body.appendChild(moreB); body.appendChild(moreBox);
        }
        body.appendChild(el("div", { class: "row", style: "margin-top:12px" }, [btn("🏠 " + t("whereNone"), "btn-ghost btn-block", function () { pick(null); })]));
      }, { now: true, lock: true, onClose: function () { if (!done) { done = true; resolve(null); } } });
    });
  }
})();
